// AWI SEO: IndexNow (Bing, Yandex, Seznam, Naver) - beri tahu mesin pencari saat konten terbit/diubah
define( 'AWI_INDEXNOW_KEY', '8356990467a2faca3ae33025c4f362bb' );
add_action( 'init', function () {
	$p = (string) wp_parse_url( $_SERVER['REQUEST_URI'], PHP_URL_PATH );
	if ( '/' . AWI_INDEXNOW_KEY . '.txt' === $p ) {
		header( 'Content-Type: text/plain; charset=utf-8' );
		echo AWI_INDEXNOW_KEY;
		exit;
	}
}, 0 );
add_action( 'transition_post_status', function ( $new, $old, $post ) {
	if ( 'publish' !== $new || wp_is_post_revision( $post ) || wp_is_post_autosave( $post ) ) {
		return;
	}
	if ( ! in_array( $post->post_type, array( 'post', 'page', 'model' ), true ) ) {
		return;
	}
	$url = get_permalink( $post );
	if ( ! $url ) {
		return;
	}
	wp_remote_post( 'https://api.indexnow.org/indexnow', array(
		'blocking' => false,
		'timeout'  => 3,
		'headers'  => array( 'Content-Type' => 'application/json; charset=utf-8' ),
		'body'     => wp_json_encode( array(
			'host'        => 'byd-makassar.id',
			'key'         => AWI_INDEXNOW_KEY,
			'keyLocation' => home_url( '/' . AWI_INDEXNOW_KEY . '.txt' ),
			'urlList'     => array( $url ),
		) ),
	) );
}, 10, 3 );
